from collections import Counter

def search(current, index, rem_sum, free_pos):
    if index == len(free_pos):
        if rem_sum == 0:
            count = Counter(current)
            if all(count.get(i, 0) == current[i] for i in range(11)):
                return True
        return False
    pos = free_pos[index]
    for val in range(rem_sum + 1):
        current[pos] = val
        if search(current, index + 1, rem_sum - val, free_pos):
            return True
    current[pos] = 0
    return False

free_pos = [0,1,2,3,5,6,7,8,9]
current = [0] * 11
current[4] = 0
current[10] = 0
found = search(current, 0, 11, free_pos)
print(found)
if found:
    print(current)
